changeSet.sql:
INSERT INTO sub_modules (name, code, module_id, enabled)
SELECT 'Sucursales', 'BRANCH', (SELECT id FROM modules WHERE code = 'GENERAL'), 1
WHERE NOT EXISTS (SELECT 1 FROM sub_modules WHERE code = 'BRANCH');

INSERT INTO base_permissions (name, code, sub_module_id, enabled)
SELECT 'Crear sucursal', 'branch.create', (SELECT id FROM sub_modules WHERE code = 'BRANCH'), 1
WHERE NOT EXISTS (SELECT 1 FROM base_permissions WHERE code = 'branch.create');

INSERT INTO base_permissions (name, code, sub_module_id, enabled)
SELECT 'Editar sucursal', 'branch.update', (SELECT id FROM sub_modules WHERE code = 'BRANCH'), 1
WHERE NOT EXISTS (SELECT 1 FROM base_permissions WHERE code = 'branch.update');
